-- Supplemental 2026 southwest Virginia indoor court research.
-- Source-linked, no invented rates, and repeat-safe.
with actor as (select id from public.profiles where role::text='admin' and coalesce(is_active,true) order by id limit 1),
data as (select * from jsonb_to_recordset($rg$[{"name":"Eureka Recreation Center","city":"Roanoke","address":"1529 Carroll Avenue NW","source_url":"https://www.playroanoke.com/parks-facilities/eureka-recreation-center/","source_label":"Roanoke Parks and Recreation — renovated 2026 gym","phone":"540-853-5454","venue_kind":"recreation_center","region_group":"Southside & Southwest","source_verification":"official","rate_details":"2026 city site rents its community ROOM, not explicitly the new hardwood basketball gym. Do not use community-room fees as basketball court rental fees.","notes":"Reopened June 2026 with new large hardwood gym. Gym rental eligibility must be confirmed with staff; do not infer from public operating hours.","source_key":"rcl-research-extended:roanoke:eureka-recreation-center","source_checked_on":"2026-10-13","rate_basis":"unknown","budget_status":"needs_quote","availability_status":"unverified","availability_details":"Specific gym rental dates, rates, and game usage are not confirmed; call facility first.","rental_allowed":null},{"name":"Andrew Lewis Middle School Gymnasium","city":"Salem","address":"616 South College Avenue","source_url":"https://www.salemva.gov/Facilities/Facility/Details/Andrew-Lewis-Middle-School-2","source_label":"City of Salem facility listing — regulation indoor basketball court","venue_kind":"school_gym","region_group":"Southside & Southwest","source_verification":"official","notes":"City directory confirms regulation indoor basketball court; school-community booking calendar does not establish specific open reservations. Request rates, school approval, and adult league access.","source_key":"rcl-research-extended:salem:andrew-lewis-middle-school-gymnasium","source_checked_on":"2026-10-13","rate_basis":"unknown","budget_status":"needs_quote","availability_status":"unverified","availability_details":"Specific gym rental dates, rates, and game usage are not confirmed; call facility first.","rental_allowed":null},{"name":"G. W. Carver Elementary School Gymnasium","city":"Salem","address":"6 East 4th Street","source_url":"https://www.salemva.gov/Facilities/Facility/Details/G-W-Carver-Elementary-School-5","source_label":"City of Salem facility directory","venue_kind":"school_gym","region_group":"Southside & Southwest","source_verification":"official","notes":"City directory explicitly states NON-REGULATION indoor basketball court. Likely unsuitable for official full-court league games; practice rental may be possible with school approval.","source_key":"rcl-research-extended:salem:g-w-carver-elementary-school-gymnasium","source_checked_on":"2026-10-13","rate_basis":"unknown","budget_status":"needs_quote","availability_status":"unverified","availability_details":"Specific gym rental dates, rates, and game usage are not confirmed; call facility first.","rental_allowed":null},{"name":"Addison Middle School Gymnasium","city":"Roanoke","address":"1220 5th Street NW","source_url":"https://www.playroanoke.com/wp-content/uploads/2019/09/2019-2028-Roanoke-Park-and-Facilities-Assessment-Final-Draft.pdf","source_label":"Roanoke Parks — 2019 facility assessment","venue_kind":"school_gym","region_group":"Southside & Southwest","source_verification":"official","notes":"Historical 2019 Roanoke assessment lists gym used by city for basketball; confirm that facility, court, rental eligibility and contact remain current in 2026.","source_key":"rcl-research-extended:roanoke:addison-middle-school-gymnasium","source_checked_on":"2026-10-13","rate_basis":"unknown","budget_status":"needs_quote","availability_status":"unverified","availability_details":"Specific gym rental dates, rates, and game usage are not confirmed; call facility first.","rental_allowed":null},{"name":"Booker T. Washington Administrative Building Gymnasium","city":"Roanoke","address":"40 Douglass Avenue NW","source_url":"https://www.playroanoke.com/wp-content/uploads/2019/09/2019-2028-Roanoke-Park-and-Facilities-Assessment-Final-Draft.pdf","source_label":"Roanoke Parks — 2019 facility assessment","venue_kind":"school_gym","region_group":"Southside & Southwest","source_verification":"official","notes":"2019 city assessment reports indoor gym basketball practice use; not independently current in 2026. School system permission required.","source_key":"rcl-research-extended:roanoke:booker-t-washington-administrative-building-gymnasium","source_checked_on":"2026-10-13","rate_basis":"unknown","budget_status":"needs_quote","availability_status":"unverified","availability_details":"Specific gym rental dates, rates, and game usage are not confirmed; call facility first.","rental_allowed":null}]$rg$::jsonb) as t(name text,city text,address text,source_url text,source_label text,phone text,venue_kind text,region_group text,source_verification text,rate_details text,notes text,source_key text,source_checked_on date,rate_basis text,budget_status text,availability_status text,availability_details text,rental_allowed boolean))
insert into public.rcl_command_venues (name,city,address,source_url,source_label,phone,venue_kind,region_group,source_verification,rate_details,notes,source_key,source_checked_on,rate_basis,budget_status,availability_status,availability_details,rental_allowed,created_by)
select data.name,data.city,data.address,data.source_url,data.source_label,data.phone,data.venue_kind,data.region_group,data.source_verification,data.rate_details,data.notes,data.source_key,data.source_checked_on,data.rate_basis,data.budget_status,data.availability_status,data.availability_details,data.rental_allowed,actor.id from data cross join actor
where not exists (select 1 from public.rcl_command_venues v where lower(v.name)=lower(data.name) and lower(v.city)=lower(data.city))
on conflict do nothing;